/* ── UTILITY FUNCTIONS ── */
function getPath(){return window.location.hash.replace('#','')||'/';}

function getEnrichment(phaseId,unitIdx){
  var e=ENRICHMENT[phaseId];
  return e&&e[unitIdx]?e[unitIdx]:null;
}

function setNav(p){
  document.querySelectorAll('.nav-link').forEach(function(a){
    a.classList.remove('active');
    if(a.getAttribute('href')==='#'+p||(p==='/'&&a.getAttribute('href')==='#/')){
      a.classList.add('active');
    }
  });
}

