/* ── PHASE DASHBOARD CARD ── */
function phaseDashCard(p){
  var phaseBook=ROG.phaseToBook[p.id];
  var bookBtn='';
  if(phaseBook&&phaseBook.id)
    bookBtn='<a href="#/books" class="pdc-btn pdc-btn-ghost">&#128218; Book Curriculum</a>';
  if(phaseBook&&phaseBook.research)
    bookBtn='<a href="#/research" class="pdc-btn pdc-btn-ghost">&#128214; Research Archive</a>';

  var roman=['I','II','III','IV','V','VI'];
  var units=p.units.slice(0,6).map(function(u,i){
    return '<a class="pdc-module" href="#/phase/'+p.id+'/unit/'+i+'">'
      +'<div class="pdc-module-dot" style="background:'+p.color+'">'+roman[i]+'</div>'
      +'<div class="pdc-module-title">'+u.t+'</div>'
      +'<div class="pdc-module-arrow">&#8594;</div>'
      +'</a>';
  }).join('');

  var ytBtn=p.playlistId?'<a href="https://www.youtube.com/playlist?list='+p.playlistId+'" target="_blank" rel="noopener" class="pdc-btn pdc-btn-ghost">&#9654;&#65039; YouTube</a>':'';
  var abBtn=p.audiobook?'<a href="'+p.audiobook.url+'" target="_blank" rel="noopener" class="pdc-btn pdc-btn-ghost">&#127911; Listen</a>':'';

  return '<div class="phase-dash-card">'
    +'<div class="pdc-hdr" style="background:linear-gradient(135deg,'+p.color+','+p.color+'cc)" onclick="window.location.hash=\'#/phase/'+p.id+'\'">'
    +'<div class="pdc-num">Phase '+p.num+'</div>'
    +'<div class="pdc-title">'+p.title+'</div>'
    +'<div class="pdc-sub">'+p.sub+'</div>'
    +'</div>'
    +'<div class="pdc-body">'
    +'<div class="pdc-desc">'+p.desc.substring(0,180)+'</div>'
    +'<div class="pdc-modules">'+units+'</div>'
    +'<div class="pdc-actions">'
    +'<a href="#/phase/'+p.id+'" class="pdc-btn pdc-btn-primary" style="background:'+p.color+'">&#9654; Open Phase</a>'
    +ytBtn+abBtn+bookBtn
    +'<a href="https://rog-access-hub.netlify.app" target="_blank" rel="noopener" class="pdc-btn pdc-btn-ghost">&#127760; Access Hub</a>'
    +'</div>'
    +'</div>'
    +'</div>';
}

