/* ── UNIT DETAIL (LESSON) ── */
function renderUnitDetail(p, idx){
  var u=p.units[idx];
  var en=getEnrichment(p.id,idx);
  var prev=idx>0?idx-1:null;
  var next=idx<p.units.length-1?idx+1:null;
  var _t=window._unitTab||'overview';

  function tabBtn(id,label,color){
    var active=_t===id;
    return '<button onclick="window._unitTab=\''+id+'\';renderUnitDetail(PHASES.find(function(x){return x.id===\''+p.id+'\';}),'+idx+')" '
      +'style="padding:8px 14px;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer;border:1.5px solid '+(active?p.color:'rgba(240,248,255,.22)')+';'
      +'background:'+(active?p.color:'rgba(240,248,255,.07)')+';color:'+(active?'#fff':'rgba(240,248,255,.82)')+'">'+label+'</button>';
  }

  var tabContent='';
  if(_t==='overview'){
    tabContent=buildOverview&&buildOverview(p,u,en)||renderOverviewFallback(p,u,en);
  } else if(_t==='quiz'){
    tabContent=en?renderQuizTab(p,idx,en):'<p style="color:rgba(240,248,255,.6);padding:20px">No quiz for this unit.</p>';
  } else if(_t==='discussion'){
    tabContent=en?renderDiscussionTab(p,idx,en):'<p style="color:rgba(240,248,255,.6);padding:20px">No discussion for this unit.</p>';
  } else if(_t==='resources'){
    tabContent=ROG.resourcesTab(p.id,idx,en);
  }

  var html=ROG.navStrip(p.id)
    +'<div style="background:var(--wine-dk,#1a0507);min-height:100vh">'
    +'<div style="background:linear-gradient(135deg,'+p.color+','+p.color+'bb);padding:32px 24px 24px">'
    +'<div style="max-width:860px;margin:0 auto">'
    +'<div style="display:flex;align-items:center;gap:8px;font-size:13px;color:rgba(255,255,255,.65);margin-bottom:12px">'
    +'<a href="#/" style="color:rgba(255,255,255,.65);text-decoration:none">Home</a>'
    +' &#8250; <a href="#/phase/'+p.id+'" style="color:rgba(255,255,255,.65);text-decoration:none">Phase '+p.num+'</a>'
    +' &#8250; <span style="color:#fff">'+u.t+'</span>'
    +'</div>'
    +'<div style="font-size:10px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.55);margin-bottom:6px">Phase '+p.num+' &mdash; Module '+(idx+1)+'</div>'
    +'<div style="font-family:var(--ff-d,Georgia,serif);font-size:clamp(18px,3.5vw,26px);font-weight:700;color:#fff;line-height:1.3;margin-bottom:8px">'+u.t+'</div>'
    +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">'
    +(prev!==null?'<button onclick="window._unitTab=\'overview\';renderUnitDetail(PHASES.find(function(x){return x.id===\''+p.id+'\';}),'+prev+')" style="padding:6px 13px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);border-radius:7px;color:#fff;font-size:12px;cursor:pointer">&#8592; Prev</button>':'')
    +(next!==null?'<button onclick="window._unitTab=\'overview\';renderUnitDetail(PHASES.find(function(x){return x.id===\''+p.id+'\';}),'+next+')" style="padding:6px 13px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);border-radius:7px;color:#fff;font-size:12px;cursor:pointer">Next &#8594;</button>':'')
    +'<a href="#/phase/'+p.id+'" style="padding:6px 13px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);border-radius:7px;color:rgba(255,255,255,.8);font-size:12px;text-decoration:none">All Modules</a>'
    +'</div></div></div>'

    +'<div style="max-width:860px;margin:0 auto;padding:20px 20px 60px">'
    +'<div style="display:flex;flex-wrap:wrap;gap:7px;margin-bottom:20px">'
    +tabBtn('overview','&#128214; Study',p.color)
    +(en?tabBtn('quiz','&#9999;&#65039; Quiz ('+en.quiz.length+')',p.color):'')
    +(en?tabBtn('discussion','&#128172; Discussion',p.color):'')
    +tabBtn('resources','&#128279; Resources',p.color)
    +'</div>'
    +'<div>'+tabContent+'</div>'
    +'</div>'
    +ROG.footer()
    +'</div>';

  var _pc=document.getElementById('phase-container');
  (_pc&&_pc.style.display!=='none'?_pc:view).innerHTML=html;
  refillLogos();
}

function renderOverviewFallback(p,u,en){
  var html='<div style="display:flex;flex-direction:column;gap:14px">';
  html+='<div style="background:rgba(240,248,255,.06);border:1px solid rgba(253,243,224,.1);border-radius:10px;padding:16px 18px">';
  html+='<div style="font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:rgba(125,204,245,.8);margin-bottom:8px">📖 Lesson Overview</div>';
  html+='<div style="font-size:14px;color:rgba(240,248,255,.85);line-height:1.7">'+(u.overview||u.desc||'Study guide for '+u.t)+'</div>';
  html+='</div>';
  if(u.scripture||u.sr){
    var sr=u.scripture||{ref:u.sr,text:u.sv||''};
    html+='<div style="background:rgba(56,168,232,.08);border-left:3px solid rgba(56,168,232,.6);border-radius:0 8px 8px 0;padding:14px 16px">';
    html+='<div style="font-size:13px;font-style:italic;color:rgba(240,248,255,.88);line-height:1.7;margin-bottom:6px">&ldquo;'+(sr.text||sr.sv||'')+'&rdquo;</div>';
    html+='<div style="font-size:11px;font-weight:700;color:rgba(56,168,232,.8)">'+(sr.ref||u.sr||'')+'</div>';
    html+='</div>';
  }
  if(en&&en.quiz&&en.quiz.length){
    html+='<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:8px">';
    html+='<button onclick="window._unitTab=\'quiz\';renderUnitDetail(PHASES.find(function(x){return x.id===\''+p.id+'\';}),'+u._idx+' || 0)" style="padding:9px 18px;background:'+p.color+';color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer">Take the Quiz &#8594;</button>';
    html+='<button onclick="window._unitTab=\'discussion\';renderUnitDetail(PHASES.find(function(x){return x.id===\''+p.id+'\';}),'+u._idx+' || 0)" style="padding:9px 18px;background:transparent;border:1.5px solid rgba(240,248,255,.22);color:rgba(240,248,255,.8);border-radius:8px;font-size:13px;font-weight:600;cursor:pointer">Discussion &#8594;</button>';
    html+='</div>';
  }
  html+='</div>';
  return html;
}

