function renderQuizTab(p, idx, en){
  if(!p||!p.color) return '';
  if(!en) return '<div style="padding:20px;text-align:center;color:var(--gray3)">Quiz coming soon for this lesson.</div>';
  const stateKey = p.id+'_'+idx;
  const qState = window._quizState && window._quizState[stateKey] || {answers:{}, submitted:false};
  let score = null;
  if(qState.submitted){
    let correct = 0;
    en.quiz.forEach((q,i)=>{ if(qState.answers[i]===q.ans) correct++; });
    score = {correct, total:en.quiz.length, pct:Math.round(correct/en.quiz.length*100)};
  }
  let html = '';
  if(score){
    html += '<div style="background:'+(score.pct>=75?'var(--green-lt)':'#FFF3E0')+';border:2px solid '+(score.pct>=75?'var(--green)':'#FB8C00')+';border-radius:10px;padding:16px 20px;text-align:center;margin-bottom:18px">'+
      '<div style="font-family:var(--ff-d);font-size:40px;font-weight:700;color:'+(score.pct>=75?'var(--green)':'#E65100')+'">'+score.pct+'%</div>'+
      '<div style="font-size:13px;color:var(--gray3);margin-top:4px">'+score.correct+' of '+score.total+' correct &mdash; '+(score.pct>=75?'&#10003; Passed!':'Try again')+'</div>'+
    '</div>';
  }
  en.quiz.forEach((q,qi)=>{
    const chosen = qState.answers[qi];
    html += '<div style="background:var(--gray1);border-radius:10px;border:1px solid var(--gray2);padding:16px 18px;margin-bottom:14px">'+
      '<div style="font-size:14px;font-weight:700;color:var(--navy);margin-bottom:12px;line-height:1.55">'+(qi+1)+'. '+q.q+'</div>'+
      q.opts.map((opt,oi)=>{
        const isChosen = chosen===oi;
        const isCorrect = oi===q.ans;
        const showOk = qState.submitted && isCorrect;
        const showWrong = qState.submitted && isChosen && !isCorrect;
        return '<button onclick="if(!('+(JSON.stringify(stateKey))+' in (window._quizState=window._quizState||{}))){window._quizState['+JSON.stringify(stateKey)+']={};}window._quizState['+JSON.stringify(stateKey)+'].answers=window._quizState['+JSON.stringify(stateKey)+'].answers||{};window._quizState['+JSON.stringify(stateKey)+'].answers['+qi+']='+oi+';if(!window._quizState['+JSON.stringify(stateKey)+'].submitted)renderUnitDetail(PHASES.find(x=>x.id==='+JSON.stringify(p.id)+'),'+idx+')" '+
          'style="display:block;width:100%;text-align:left;padding:10px 14px;margin-bottom:7px;border-radius:8px;cursor:'+(qState.submitted?'default':'pointer')+';'+
          'border:1.5px solid '+(showOk?'var(--green)':showWrong?'#e53935':isChosen?p.color:'var(--gray2)')+';'+
          'background:'+(showOk?'var(--green-lt)':showWrong?'#FFEBEE':isChosen?'#EEF3FB':'var(--white)')+';'+
          'font-size:13px;line-height:1.5;color:var(--text)">'+
          (showOk?'&#10003; ':showWrong?'&#10007; ':'')+opt+'</button>';
      }).join('')+
    '</div>';
  });
  if(!qState.submitted){
    html += '<button class="btn btn-navy" onclick="window._quizState=window._quizState||{};window._quizState['+JSON.stringify(stateKey)+']=(window._quizState['+JSON.stringify(stateKey)+']||{});window._quizState['+JSON.stringify(stateKey)+'].submitted=true;renderUnitDetail(PHASES.find(x=>x.id==='+JSON.stringify(p.id)+'),'+idx+')">Submit Quiz</button>';
  } else {
    html += '<button class="btn" style="background:var(--gray3);color:#fff;margin-right:8px" onclick="window._quizState['+JSON.stringify(stateKey)+']={answers:{},submitted:false};renderUnitDetail(PHASES.find(x=>x.id==='+JSON.stringify(p.id)+'),'+idx+')">Retake</button>'+
      '<button class="btn btn-navy" onclick="window._unitTab=\'discussion\';renderUnitDetail(PHASES.find(x=>x.id==='+JSON.stringify(p.id)+'),'+idx+')">Join Discussion &#8594;</button>';
  }
  return html;
}

function renderDiscussionTab(p, idx, en){
  if(!en) return '<div style="padding:20px;text-align:center;color:var(--gray3)">Discussion prompts coming soon.</div>';
  let html = '<div style="background:var(--gray1);border-left:3px solid '+p.color+';padding:12px 16px;border-radius:0 8px 8px 0;margin-bottom:20px;font-size:14px;color:var(--text)">'+
    '&#128172; <strong>Thread Discussion Prompts</strong> &mdash; Use these in your training group, small group, or for personal reflection. Allow 10&ndash;15 minutes per prompt.'+
  '</div>';
  en.discussion.forEach((d,di)=>{
    html += '<div style="display:flex;gap:14px;align-items:flex-start;padding:16px 18px;background:var(--white);border-radius:10px;border:1px solid var(--gray2);margin-bottom:12px">'+
      '<div style="width:28px;height:28px;border-radius:50%;background:'+p.color+';color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px">D'+(di+1)+'</div>'+
      '<div style="font-size:14px;color:var(--text);line-height:1.7;flex:1">'+d+'</div>'+
    '</div>';
  });
  html += '<div style="margin-top:20px;background:var(--gold-pale);border-radius:10px;border:1px solid rgba(184,134,11,.25);padding:14px 18px">'+
    '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--gold);margin-bottom:6px">&#128221; Facilitator Notes</div>'+
    '<div style="font-size:13px;color:var(--text);line-height:1.7">Encourage participants to share from personal experience first before moving to theological reflection. The goal is honest engagement, not a right answer. These prompts work for both scholarly and lay groups — adapt the depth to your audience.</div>'+
  '</div>'+
  '<div style="margin-top:14px;display:flex;gap:8px;flex-wrap:wrap">'+
    '<button class="btn btn-soft" onclick="window._unitTab=\'overview\';renderUnitDetail(PHASES.find(x=>x.id==='+JSON.stringify(p.id)+'),'+idx+')">&#8592; Back to Lesson</button>'+
    (getEnrichment(p.id,idx)?'<button class="btn btn-navy" onclick="window._unitTab=\'quiz\';renderUnitDetail(PHASES.find(x=>x.id==='+JSON.stringify(p.id)+'),'+idx+')">Take the Quiz &#8594;</button>':'')+
  '</div>';
  
  /* ── Quick resource links at bottom of discussion ── */
  if(en&&(en.biblical&&en.biblical.length||en.videos&&en.videos.length)){
    html+='<div style="margin-top:20px;padding:14px 16px;background:rgba(56,168,232,.07);border:1px solid rgba(56,168,232,.18);border-radius:10px">';
    html+='<div style="font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:rgba(56,168,232,.7);margin-bottom:10px">📚 Quick Resources</div>';
    html+='<div style="display:flex;flex-wrap:wrap;gap:7px">';
    if(en.biblical)en.biblical.forEach(function(r){
      if(r.url) html+='<a href="'+r.url+'" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:5px;padding:5px 11px;border-radius:6px;font-size:12px;font-weight:600;text-decoration:none;background:rgba(240,248,255,.07);border:1px solid rgba(240,248,255,.18);color:rgba(240,248,255,.8)">'+(r.icon||'📖')+' '+(r.title||r.name||'')+'</a>';
    });
    if(en.videos)en.videos.forEach(function(v){
      if(v.url) html+='<a href="'+v.url+'" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:5px;padding:5px 11px;border-radius:6px;font-size:12px;font-weight:600;text-decoration:none;background:rgba(240,248,255,.07);border:1px solid rgba(240,248,255,.18);color:rgba(240,248,255,.8)">▶️ '+(v.title||v.name||'').substring(0,35)+'</a>';
    });
    html+='</div></div>';
  }
  return html;
}

