function resModule(num,title,chip,session,subject,intro,primary,crossrefs,quote,quoteRef,hermeneutics,points,disc,lifeApp,bibleRefs,threadPrompt,reviewQs,lifeClose){
  var id='res-mod-'+num;
  var pts=Array.isArray(points)?points.map(function(p){return '<li style="margin-bottom:8px">'+p+'</li>';}).join(''):'';
  var qs=Array.isArray(reviewQs)&&Array.isArray(reviewQs[0])?reviewQs[0].map(function(q){return '<li style="margin-bottom:8px">'+q+'</li>';}).join(''):'';
  return '<details style="border:1px solid rgba(240,248,255,.18);border-radius:4px;background:rgba(240,248,255,.05);margin-bottom:10px;overflow:hidden" id="'+id+'">'
    +'<summary style="list-style:none;cursor:pointer;padding:16px 20px;display:flex;align-items:baseline;gap:14px">'
    +'<span style="font-weight:700;color:var(--gold,#38A8E8);font-size:14px;white-space:nowrap">Module '+num+'</span>'
    +'<span style="font-family:var(--ff-d,Georgia,serif);font-weight:600;color:var(--parchment,#F0F8FF);font-size:17px;flex:1">'+title+'</span>'
    +'<span style="font-size:12px;color:rgba(240,248,255,.5);border:1px solid rgba(240,248,255,.18);padding:3px 9px;border-radius:20px;white-space:nowrap">'+chip+'</span>'
    +'</summary>'
    +'<div style="padding:4px 24px 28px 24px;border-top:1px solid rgba(253,243,224,.1)">'
    +(studyBar?studyBar({phaseId:'phase13',unitIdx:num-1,phaseColor:'#6B2A00',context:'research'}):'')
    +'<p style="color:rgba(240,248,255,.55);font-size:13px;margin:16px 0 0">Session: <em>'+session+'</em></p>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Subject</h4><p style="font-size:14px;line-height:1.8;color:rgba(240,248,255,.85)">'+subject+'</p>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Introduction</h4><p style="font-size:14px;line-height:1.8;color:rgba(240,248,255,.85)">'+intro+'</p>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Scripture</h4>'
    +'<p style="font-size:13px"><strong>Primary:</strong> '+primary+'<br><strong>Cross-refs:</strong> '+crossrefs+'</p>'
    +'<blockquote style="margin:10px 0;padding:10px 16px;border-left:3px solid var(--gold,#38A8E8);background:rgba(56,168,232,.08);font-style:italic;color:rgba(240,248,255,.9);font-size:14px">&ldquo;'+quote+'&rdquo; <cite style="display:block;font-style:normal;font-weight:700;color:var(--gold,#38A8E8);font-size:12px;margin-top:4px">&mdash; '+quoteRef+'</cite></blockquote>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Hermeneutics</h4><p style="font-size:14px;line-height:1.8;color:rgba(240,248,255,.85)">'+hermeneutics+'</p>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Top 6 Study Points</h4>'
    +'<ol style="margin:0 0 14px;padding-left:22px;font-size:14px;line-height:1.8;color:rgba(240,248,255,.85)">'+pts+'</ol>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Discussion</h4>'
    +'<p style="font-size:14px;margin:0 0 8px;color:rgba(240,248,255,.85)"><strong>Topic:</strong> '+disc+'</p>'
    +'<p style="font-size:14px;margin:0 0 8px;color:rgba(240,248,255,.85)"><strong>Life Application:</strong> '+lifeApp+'</p>'
    +'<p style="font-size:14px;margin:0 0 12px;color:rgba(240,248,255,.85)"><strong>References:</strong> '+bibleRefs+'</p>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Threaded Discussion Forum</h4>'
    +'<p style="font-size:14px;font-style:italic;color:rgba(240,248,255,.7)">'+threadPrompt+'</p>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Review Questions</h4>'
    +'<ol style="margin:0 0 14px;padding-left:22px;font-size:14px;line-height:1.8;color:rgba(240,248,255,.85)">'+qs+'</ol>'
    +'<h4 style="color:var(--parchment,#F0F8FF);margin:20px 0 8px">Life Application</h4>'
    +'<p style="font-size:14px;line-height:1.8;color:rgba(240,248,255,.85)">'+lifeClose+'</p>'
    +'</div></details>';
}

