document.addEventListener('DOMContentLoaded', render);
window.addEventListener('hashchange', render);
window.addEventListener('load', render);
document.addEventListener('DOMContentLoaded',function(){
  var nt=document.getElementById('navToggle');
  var nl=document.getElementById('navLinks');
  if(nt&&nl){
    nt.addEventListener('click',function(){nl.classList.toggle('open');});
    nl.addEventListener('click',function(e){if(e.target.tagName==='A'&&!e.target.getAttribute('target'))nl.classList.remove('open');});
  }
  window.addEventListener('scroll',function(){
    var nb=document.getElementById('navbar');
    if(nb)nb.classList.toggle('scrolled',window.scrollY>20);
  });
});
if(document.readyState==='complete'||document.readyState==='interactive'){render();}


function renderResourcesTab(p, idx, en){
  return ROG.resourcesTab(p.id, idx, en);
}

